function authAside(){return `<aside class="aside"><span class="eyebrow">SHPROHLI</span><h2>${T('A little help.<br>A call made easier.','Ein wenig Hilfe.<br>Ein leichterer Anruf.')}</h2><p class="lead">${T('Prepare your request, review the plan and stay in control.','Bereiten Sie Ihr Anliegen vor, prüfen Sie den Plan und behalten Sie die Kontrolle.')}</p><div class="section"><div class="stack tight"><span>${T('3 calls included in the public beta','3 Anrufe in der öffentlichen Beta enthalten')}</span><span class="help">${T('Swiss numbers only. The recipient chooses whether to continue.','Nur Schweizer Nummern. Die angerufene Person entscheidet, ob sie fortfahren möchte.')}</span></div></div></aside>`}
function authPage(){let body='';const email=()=>field(T('Email address','E-Mail-Adresse'),'',{type:'email',placeholder:'nina@example.com',required:true,maxLength:320});const password=(label=T('Password','Passwort'),confirm=false)=>field(label,'',{type:'password',required:true,minLength:12,maxLength:128,help:confirm?'':T('Use at least 12 characters.','Verwenden Sie mindestens 12 Zeichen.')});const code=()=>field(T('SMS verification code','SMS-Bestätigungscode'),'',{required:true,numeric:true,minLength:4,maxLength:10,placeholder:'000000',error:state('invalid-code')?T('This code is invalid or expired. Request a new code.','Dieser Code ist ungültig oder abgelaufen. Fordern Sie einen neuen Code an.'):''});
 if(ctx.id==='register')body=intro(T('Create your SHPROHLI account','SHPROHLI-Konto erstellen'),T('Use your real first and last name. The assistant uses them when calling on your behalf.','Verwenden Sie Ihren echten Vor- und Nachnamen. Der Assistent nennt sie bei Anrufen in Ihrem Namen.'))+form(`${state('error')?note(T('Please check the highlighted fields.','Prüfen Sie die markierten Felder.'),'error'):''}<div class="grid2">${field(T('First name','Vorname'),'',{placeholder:'Nina',required:true,maxLength:80})}${field(T('Last name','Nachname'),'',{placeholder:'Keller',required:true,maxLength:80})}</div>${email()}${field(T('Mobile phone','Mobiltelefon'),'',{type:'tel',placeholder:'+41791234567',required:true,help:T('Use international format. We will send a verification code by SMS.','Im internationalen Format. Sie erhalten einen Bestätigungscode per SMS.'),error:state('error')?T('Enter a valid international phone number.','Geben Sie eine gültige internationale Telefonnummer ein.'):''})}${password()}${submit(state('busy')?T('Creating account…','Konto wird erstellt…'):T('Create account','Konto erstellen'),state('busy'))}<p class="help">${T('Already have an account?','Sie haben bereits ein Konto?')} ${link(T('Sign in','Anmelden'),'login')}</p>`,'default','verify');
 if(ctx.id==='login')body=intro(T('Welcome back','Willkommen zurück'),T('Sign in to prepare and supervise your calls.','Melden Sie sich an, um Ihre Anrufe vorzubereiten und zu begleiten.'))+form(`${state('error')?note(T('The email or password is incorrect.','E-Mail oder Passwort ist nicht korrekt.'),'error'):''}${state('suspended')?note(T('Your account is suspended. Contact support for help.','Ihr Konto ist gesperrt. Wenden Sie sich an den Support.'),'error'):''}${state('rate-limited')?note(T('Too many attempts. Wait before trying again.','Zu viele Versuche. Warten Sie, bevor Sie es erneut versuchen.'),'warning'):''}${state('verification-required')?note(T('Verify your phone number to continue.','Bestätigen Sie Ihre Telefonnummer, um fortzufahren.')+' '+link(T('Verify phone','Telefon bestätigen'),'verify'),'warning'):''}${email()}${password()}${link(T('Forgot your password?','Passwort vergessen?'),'recover')}${submit(T('Sign in','Anmelden'))}<p class="help">${T('New to SHPROHLI?','Neu bei SHPROHLI?')} ${link(T('Create an account','Konto erstellen'),'register')}</p>`,'default','new-call');
 if(ctx.id==='verify')body=intro(T('Verify your phone','Telefonnummer bestätigen'),T('Enter the code sent to your mobile phone.','Geben Sie den Code ein, der an Ihr Mobiltelefon gesendet wurde.'))+form(`${state('resent')?note(T('A new verification code was sent.','Ein neuer Bestätigungscode wurde gesendet.')):''}${email()}${code()}${submit(state('busy')?T('Verifying…','Wird bestätigt…'):T('Verify and continue','Bestätigen und weiter'),state('busy'))}${btn(T('Send a new code','Neuen Code senden'),'resent','quiet')}${link(T('Back to registration','Zurück zur Registrierung'),'register')}`,'default','onboarding');
 if(ctx.id==='recover'){
  let step=state('verify')?2:state('reset')?3:1;
  body=intro(T('Recover your account','Kontozugriff wiederherstellen'),T('Use your verified mobile phone to set a new password.','Verwenden Sie Ihr bestätigtes Mobiltelefon, um ein neues Passwort festzulegen.'));
  if(state('success'))body+=note(T('Password changed. Existing sessions have been signed out.','Passwort geändert. Bestehende Sitzungen wurden abgemeldet.'))+`<div class="actions">${link(T('Go to sign in','Zur Anmeldung'),'login','default','button primary')}</div>`;
  else body+=form(`<span class="help">${T('Step','Schritt')} ${step} / 3</span>${state('expired')?note(T('This approval has expired. Start recovery again.','Diese Freigabe ist abgelaufen. Starten Sie die Wiederherstellung erneut.'),'warning'):''}${state('error')?note(T('Recovery could not be completed. Check your details and try again.','Die Wiederherstellung konnte nicht abgeschlossen werden.'),'error'):''}${step===1?email():step===2?code():password(T('New password','Neues Passwort'))+password(T('Confirm new password','Neues Passwort bestätigen'),true)}${step===3?'<p class="help">'+T('Your reset approval expires after 15 minutes.','Die Freigabe läuft nach 15 Minuten ab.')+'</p>':''}${submit(step===1?T('Send recovery code','Wiederherstellungscode senden'):step===2?T('Verify code','Code bestätigen'):T('Set new password','Neues Passwort speichern'))}${link(T('Back to sign in','Zurück zur Anmeldung'),'login')}`,step===1?'verify':step===2?'reset':'success');
 }
 if(ctx.id==='onboarding')body=intro(T('Before your first call','Vor Ihrem ersten Anruf'),T('Please review how SHPROHLI works and the documents below.','Bitte lesen Sie, wie SHPROHLI funktioniert, und prüfen Sie die folgenden Dokumente.'))+form(`${state('error')?note(T('Your acceptance could not be saved. Please try again.','Ihre Zustimmung konnte nicht gespeichert werden.'),'error'):''}${state('revision-changed')?note(T('The documents have changed. Review the current revision before continuing.','Die Dokumente wurden geändert. Lesen Sie die aktuelle Version, bevor Sie fortfahren.'),'warning'):''}<div class="stack tight">${link(T('Terms of Use','Nutzungsbedingungen'),'terms')}${link(T('Acceptable Use Policy','Nutzungsregeln'),'acceptable-use')}${link(T('Privacy Notice','Datenschutzhinweise'),'privacy')}</div><div class="section"><p>${T('You approve the call plan before any call starts.','Sie genehmigen den Anrufplan, bevor ein Anruf beginnt.')}</p><p>${T('The recipient chooses whether to continue. AI-generated transcripts can contain errors.','Die angerufene Person entscheidet, ob sie fortfahren möchte. KI-generierte Transkripte können Fehler enthalten.')}</p><p>${T('Use SHPROHLI for low-risk everyday calls. It is not an emergency service.','Nutzen Sie SHPROHLI für alltägliche Anrufe mit geringem Risiko. Es ist kein Notfalldienst.')}</p></div>${check(T('I agree to the Terms of Use and Acceptable Use Policy.','Ich stimme den Nutzungsbedingungen und Nutzungsregeln zu.'),state('accepted'),true)}${submit(T('Agree and continue','Zustimmen und fortfahren'))}${link(T('Sign out','Abmelden'),'login')}`,'default','new-call');
 return header()+`<main id="main-content" class="auth ${ctx.id==='onboarding'?'single':''}">${ctx.id==='onboarding'?'':authAside()}<div class="form-area">${body}</div></main>`+footer();
}

function landingPage(){const demo=`<div class="hero-demo"><span class="eyebrow">${T('Example call plan','Beispiel-Anrufplan')}</span><h3>${T('Municipal office','Gemeinde')}</h3><p>${T('Check whether my residence form arrived.','Prüfen, ob mein Formular eingegangen ist.')}</p><ol class="step-list"><li><div><strong>${T('Prepare your request','Anliegen vorbereiten')}</strong><p>${T('Tell SHPROHLI what you need.','Beschreiben Sie Ihr Anliegen.')}</p></div></li><li><div><strong>${T('Review the plan','Plan prüfen')}</strong><p>${T('Check the goal and the information that may be shared.','Prüfen Sie Ziel und freigegebene Informationen.')}</p></div></li><li><div><strong>${T('Approve the call','Anruf freigeben')}</strong><p>${T('The call starts only after you approve.','Der Anruf beginnt erst nach Ihrer Freigabe.')}</p></div></li></ol></div>`;
 const uses=[[T("Doctor’s practice","Arztpraxis"),T('Ask about an appointment or a document.','Nach einem Termin oder Dokument fragen.')],[T('Municipal office (Gemeinde)','Gemeinde'),T('Check whether an application arrived and whether anything is missing.','Prüfen, ob ein Antrag eingegangen ist und Unterlagen fehlen.')],[T('School or course provider','Schule oder Kursanbieter'),T('Ask about schedules, registration or a payment.','Nach Stundenplan, Anmeldung oder einer Zahlung fragen.')],[T('Landlord or repair service','Vermietung oder Reparaturdienst'),T('Report a practical issue and ask about the next step.','Ein praktisches Problem melden und den nächsten Schritt klären.')],[T('Insurance administration','Versicherungsadministration'),T('Ask about a document, form or status.','Nach einem Dokument, Formular oder Status fragen.')]];
 const faq=PUBLIC_CONTENT.faq[ctx.lang]||PUBLIC_CONTENT.faq.en;let faqs='';for(let i=0;i<faq.length;i++)if(faq[i].tag==='h2'){faqs+=`<details><summary>${esc(faq[i].text)}</summary><p>${esc(faq[i+1]?.text||'')}</p></details>`}
 return header()+(ctx.id==='preview-landing'||state('preview')?previewBanner():'')+`<main id="main-content" class="container"><section class="hero"><div><span class="eyebrow">${T('Phone calls, made more accessible','Telefonanrufe, leichter zugänglich')}</span><h1>${T('Need to make a phone call, but <span class="accent">speaking</span> is the hard part?','Sie müssen telefonieren, aber das <span class="accent">Sprechen</span> fällt schwer?')}</h1><p class="supporting">${T('SHPROHLI can make the call for you.','SHPROHLI kann den Anruf für Sie übernehmen.')}</p><p class="muted">${T('Tell SHPROHLI what you need, review the call plan and let the AI assistant make the call on your behalf.','Beschreiben Sie Ihr Anliegen, prüfen Sie den Anrufplan und lassen Sie den KI-Assistenten in Ihrem Namen anrufen.')}</p><p class="help">${T('For people who find speaking on the phone difficult and anyone who needs help calling in a local language.','Für Menschen, denen das Sprechen am Telefon schwerfällt, und alle, die Hilfe bei Anrufen in einer lokalen Sprache benötigen.')}</p><div class="actions">${link(T('Try SHPROHLI','SHPROHLI ausprobieren'),'register','default','button primary')}<a class="button quiet" href="#how-it-works">${T('See how it works','So funktioniert es')}</a></div><div class="row" style="margin-top:24px">${badge(T('Free public beta','Kostenlose öffentliche Beta'),'neutral')}${badge(T('3 calls included','3 Anrufe enthalten'),'neutral')}${badge(T('Swiss numbers only','Nur Schweizer Nummern'),'neutral')}</div></div>${demo}</section><section class="landing-section"><span class="eyebrow">${T('Why SHPROHLI','Warum SHPROHLI')}</span><h2>${T('Some calls are harder than they should be.','Manche Anrufe sind schwieriger, als sie sein sollten.')}</h2><div class="grid2"><div class="stack tight"><h3>${T('Speaking is difficult','Das Sprechen fällt schwer')}</h3><p class="muted">${T('A speech impairment, fatigue or a communication difficulty can turn a short call into a barrier.','Eine Sprachbeeinträchtigung, Erschöpfung oder Kommunikationsschwierigkeit kann einen kurzen Anruf zu einer Hürde machen.')}</p></div><div class="stack tight"><h3>${T('The local language is a barrier','Die lokale Sprache ist eine Hürde')}</h3><p class="muted">${T('Calling an authority or service in a local language can be confusing and exhausting.','Ein Anruf bei einer Behörde oder einem Dienstleister in der lokalen Sprache kann verwirrend und anstrengend sein.')}</p></div></div></section><section class="landing-section"><span class="eyebrow">${T('Everyday calls','Alltägliche Anrufe')}</span><h2>${T('Calls SHPROHLI can help with','Anrufe, bei denen SHPROHLI helfen kann')}</h2>${uses.map(([h,p])=>`<div class="use-row"><h3>${h}</h3><p class="muted">${p}</p></div>`).join('')}</section><section class="landing-section"><h2>${T('From one sentence to a completed call','Von einem Satz zum abgeschlossenen Anruf')}</h2><div class="grid2"><div class="stack"><span class="eyebrow">${T('Your request','Ihr Anliegen')}</span><h3>${T('“Ask the Gemeinde whether my residence form arrived and if any documents are missing.”','„Frage die Gemeinde, ob mein Formular eingegangen ist und ob Unterlagen fehlen.“')}</h3><p class="muted">${T('SHPROHLI prepares a plan for your review. You decide when the call may start.','SHPROHLI erstellt einen Plan zur Prüfung. Sie entscheiden, wann der Anruf beginnen darf.')}</p></div><div class="surface stack"><span class="eyebrow">${T('Example result','Beispielergebnis')}</span><h3>${T('The form arrived. One document is still needed.','Das Formular ist eingegangen. Ein Dokument fehlt noch.')}</h3><p>${T('The office asks for a copy of the passport by email.','Die Gemeinde bittet um eine Passkopie per E-Mail.')}</p><small>${T('Illustrative everyday call, not a guaranteed outcome.','Beispiel eines alltäglichen Anrufs, kein garantiertes Ergebnis.')}</small></div></div></section><section class="landing-section" id="how-it-works"><span class="eyebrow">${T('How it works','So funktioniert es')}</span><h2>${T('You stay in control from start to finish.','Sie behalten von Anfang bis Ende die Kontrolle.')}</h2><ol class="step-list">${[[T('Tell SHPROHLI what you need','Beschreiben Sie Ihr Anliegen'),T('Choose the recipient, call language and goal.','Wählen Sie Empfänger, Anrufsprache und Ziel.')],[T('Check the call plan','Prüfen Sie den Anrufplan'),T('Review the goal, opening and approved information.','Prüfen Sie Ziel, Einleitung und freigegebene Informationen.')],[T('Approve the call','Geben Sie den Anruf frei'),T('The assistant identifies itself and asks the recipient for consent.','Der Assistent stellt sich vor und bittet die angerufene Person um Zustimmung.')],[T('See the results','Sehen Sie das Ergebnis'),T('Follow the conversation and read the final transcript.','Verfolgen Sie das Gespräch und lesen Sie das endgültige Transkript.')]].map(([h,p])=>`<li><div><h3>${h}</h3><p>${p}</p></div></li>`).join('')}</ol></section><section class="landing-section"><span class="eyebrow">${T('Control and transparency','Kontrolle und Transparenz')}</span><h2>${T('Clear limits for everyday calls.','Klare Grenzen für alltägliche Anrufe.')}</h2><div class="grid2"><div class="stack"><p>${T('You approve every call. The recipient hears that an AI assistant is calling and chooses whether to continue.','Sie genehmigen jeden Anruf. Die angerufene Person erfährt, dass ein KI-Assistent anruft, und entscheidet über die Fortsetzung.')}</p><p class="muted">${T('Transcripts may contain errors. Choose how long recordings are kept and review important details.','Transkripte können Fehler enthalten. Wählen Sie die Aufbewahrungsdauer und prüfen Sie wichtige Angaben.')}</p></div>${note(T('Not for emergencies, harassment, mass marketing or high-risk decisions.','Nicht für Notfälle, Belästigung, Massenwerbung oder Entscheidungen mit hohem Risiko.'),'warning')}</div></section><section class="landing-section"><span class="eyebrow">${T('Languages','Sprachen')}</span><h2>${T('The interface language is not the call language.','Oberflächensprache und Anrufsprache sind unabhängig.')}</h2><p class="muted">${T('Use the interface in English or German. Choose the spoken language separately for each call.','Nutzen Sie die Oberfläche auf Englisch oder Deutsch. Wählen Sie die gesprochene Sprache für jeden Anruf separat.')}</p><div class="row" style="margin-top:24px">${['Deutsch (Schweiz)','Deutsch (Deutschland)','Français (Suisse)','Italiano (Svizzera)','English (UK)','English (US)','Русский'].map(x=>badge(x,'neutral')).join('')}</div></section><section class="landing-section faq"><h2>FAQ</h2>${faqs}${link(T('Read all questions','Alle Fragen lesen'),'faq')}</section><section class="landing-section center"><h2 style="margin:0 auto 20px">${T('A call you’ve been putting off?','Ein Anruf, den Sie aufgeschoben haben?')}</h2><p class="muted" style="margin:auto">${T('Start with three calls in the free public beta.','Beginnen Sie mit drei Anrufen in der kostenlosen öffentlichen Beta.')}</p><div class="actions" style="justify-content:center;margin-top:24px">${link(T('Create account','Konto erstellen'),'register','default','button primary')}</div></section></main>`+footer();
}

function docPage(){const key=ctx.id==='preview-content'?'acceptable-use':ctx.id,nodes=PUBLIC_CONTENT[key]?.[ctx.lang]||PUBLIC_CONTENT[key]?.en||[];return header()+(ctx.id==='preview-content'?previewBanner():'')+`<main class="container article-layout" id="main-content"><nav class="sidenav" aria-label="${T('Public pages','Öffentliche Seiten')}">${[['FAQ','faq'],[T('Support','Hilfe'),'support'],[T('Privacy','Datenschutz'),'privacy'],[T('Terms','Bedingungen'),'terms'],[T('Acceptable Use','Nutzungsregeln'),'acceptable-use'],[T('Imprint','Impressum'),'imprint']].map(([l,id])=>link(l,id,'default',key===id?'active':'')).join('')}</nav><article class="article-content">${nodes.map(n=>`<${n.tag} ${n.tag==='a'?`href="${esc(n.href)}"`:''} ${n.tag==='a'?`href="${esc(n.href+(n.href.startsWith('mock.html')?'&theme='+ctx.theme:''))}"`:''} ${n.tag==='p'&&/Version|Effective|Gültig|Stand/.test(n.text)?'class="doc-meta"':''}>${esc(n.text)}</${n.tag}>`).join('')}${ctx.id==='support'?`<div class="actions"><a class="button" href="mailto:support@shprohli.ch">support@shprohli.ch</a>${link(T('Block unwanted calls','Unerwünschte Anrufe blockieren'),'opt-out','default','button quiet')}</div>`:''}</article></main>`+footer()}

function smallFlow(){const redeem=ctx.id==='redeem';let body=intro(redeem?T('Redeem a promo code','Aktionscode einlösen'):T('Stop future calls','Künftige Anrufe stoppen'),redeem?T('Enter a SHPROHLI promo code. A valid code is applied once and your balance updates immediately.','Geben Sie einen SHPROHLI-Aktionscode ein. Ein gültiger Code wird einmal angewendet und Ihr Guthaben sofort aktualisiert.'):T('Verify your phone number to block future SHPROHLI calls across all accounts.','Bestätigen Sie Ihre Telefonnummer, um künftige SHPROHLI-Anrufe aus allen Konten zu blockieren.'),redeem?T('Call credits','Anrufguthaben'):T('Recipient controls','Kontrolle für Empfänger'));
 if(state('success'))body+=note(redeem?T('3 credits were added to your balance.','3 Guthaben wurden Ihrem Konto hinzugefügt.'):T('Future SHPROHLI calls to this number are blocked.','Künftige SHPROHLI-Anrufe an diese Nummer sind blockiert.'))+`<div class="actions">${link(redeem?T('Prepare a call','Anruf vorbereiten'):T('Back to home','Zur Startseite'),redeem?'new-call':'landing','default','button primary')}</div>`;
 else if(state('sign-in'))body+=empty(T('Sign in required','Anmeldung erforderlich'),T('Sign in to redeem a promo code.','Melden Sie sich an, um einen Aktionscode einzulösen.'),link(T('Sign in','Anmelden'),'login','default','button primary'));
 else body+=form(`${['invalid','used','error','rate-limited'].includes(ctx.state)?note(state('used')?T('You have already used this promo code the maximum number of times.','Sie haben diesen Aktionscode bereits so oft wie erlaubt verwendet.'):state('rate-limited')?T('Too many promo attempts. Wait before trying again.','Zu viele Versuche. Warten Sie vor einem weiteren Versuch.'):redeem?T('This code is invalid, inactive, not yet valid or expired.','Dieser Code ist ungültig, inaktiv, noch nicht gültig oder abgelaufen.'):T('The code could not be verified. Check it and try again.','Der Code konnte nicht bestätigt werden.'),'error'):''}${redeem?field(T('Promo code','Aktionscode'),'',{placeholder:'SHPROHLI25',required:true}):state('verify')?field(T('SMS verification code','SMS-Bestätigungscode'),'',{placeholder:'000000',numeric:true,required:true,minLength:4,maxLength:10,help:T('Sent to +41 79 ••• 45 67','Gesendet an +41 79 ••• 45 67')}):field(T('Phone number','Telefonnummer'),'',{type:'tel',placeholder:'+41791234567',required:true})}${submit(redeem?T('Redeem code','Code einlösen'):state('verify')?T('Verify and block calls','Bestätigen und Anrufe blockieren'):T('Send verification code','Bestätigungscode senden'))}${!redeem&&state('verify')?btn(T('Send a new code','Neuen Code senden'),'verify','quiet'):''}`,redeem||state('verify')?'success':'verify');
 return header(redeem?'customer':'public')+`<main id="main-content" class="auth single"><div class="form-area">${body}</div></main>`+footer();
}

const callLanguages=['German (Switzerland)','German (Germany)','French (Switzerland)','Italian (Switzerland)','English (UK)','English (US)','Russian'];
function callForm(){const filled=!['default','empty','error','no-credits','active-call','paused'].includes(ctx.state);let notice=state('no-credits')?note(T('You need a call credit before starting another call.','Sie benötigen Anrufguthaben, bevor Sie einen weiteren Anruf starten.')+' '+link(T('Redeem code','Code einlösen'),'redeem'),'warning'):state('active-call')?note(T('Another call is active. Open it before preparing a new one.','Ein anderer Anruf ist aktiv. Öffnen Sie ihn, bevor Sie einen neuen vorbereiten.')+' '+link(T('Open active call','Aktiven Anruf öffnen'),'call','live'),'warning'):state('paused')?note(T('New outbound calls are temporarily paused.','Neue ausgehende Anrufe sind vorübergehend pausiert.'),'warning'):state('error')?note(T('The plan could not be prepared. Your input is preserved.','Der Plan konnte nicht erstellt werden. Ihre Eingaben bleiben erhalten.'),'error'):'';
 return `<div class="intro"><div class="row between"><div><h1>${T('Who are we calling, and why?','Wen rufen wir an, und warum?')}</h1><p style="margin-top:12px">${T('Prepare a plan. Review it before the call.','Bereiten Sie einen Plan vor. Prüfen Sie ihn vor dem Anruf.')}</p></div><div><strong class="accent" data-progress>${filled?'5':'0'}/5</strong><small style="display:block">${T('required fields completed','Pflichtfelder ausgefüllt')}</small><div class="progress-track"><i style="width:${filled?'100%':'0'}"></i></div></div></div></div>${notice}<form class="native-form" id="call-form" data-next="review" data-page="call"><div class="section"><div class="section-title">${T('Recipient','Empfänger')}</div>${field(T('Organisation or recipient','Organisation oder Empfänger'),filled?T('Municipal office','Gemeinde'):'',{placeholder:T('e.g. Dr. Schmidt or Example Council','z. B. Dr. Schmidt oder Gemeinde'),required:true})}<div class="grid2">${field(T('Phone number','Telefonnummer'),filled?'+41441234567':'',{type:'tel',placeholder:'+41…',required:true,help:T('Swiss phone numbers only during public beta.','In der öffentlichen Beta nur Schweizer Telefonnummern.')})}${field(T('Call language','Anrufsprache'),callLanguages[0],{options:callLanguages})}</div></div><div class="section"><div class="section-title">${T('Task','Aufgabe')}</div>${field(T('What should the assistant do?','Was soll der Assistent tun?'),filled?T('Check whether my residence form arrived and whether any documents are missing.','Prüfen, ob mein Formular eingegangen ist und ob Unterlagen fehlen.'):'',{type:'textarea',maxLength:4000,required:true,placeholder:T('Describe the goal naturally, in any language.','Beschreiben Sie das Ziel natürlich, in einer beliebigen Sprache.'),help:T('0 / 4000 characters','0 / 4000 Zeichen')})}</div><div class="section"><div class="section-title">${T('Assistant','Assistent')}</div><div class="grid2">${field(T('AI assistant','KI-Assistent'),'Sebastian',{options:['Sebastian','Daniel','Martin','Anna','Sofia','Maria']})}${field(T('Reason for assistance','Grund der Unterstützung'),T('Do not disclose a reason','Keinen Grund offenlegen'),{options:[T('Do not disclose a reason','Keinen Grund offenlegen'),T('Speech impairment','Sprachbeeinträchtigung'),T('Language barrier','Sprachbarriere')],help:T('If selected, the reason may be shared with the person called.','Ein gewählter Grund kann der angerufenen Person mitgeteilt werden.')})}</div><div class="grid2">${field(T("Represented person’s first name",'Vorname der vertretenen Person'),filled?'Nina':'',{placeholder:'Nina',required:true,maxLength:80})}${field(T("Represented person’s last name",'Nachname der vertretenen Person'),filled?'Keller':'',{placeholder:'Keller',required:true,maxLength:80})}</div><details class="disclosure" ${state('options')?'open':''}><summary>${T('Call options','Anrufoptionen')}</summary><div class="stack"><p class="help">${T('Safe defaults work for most calls. Change only what matters for this conversation.','Sichere Standardwerte eignen sich für die meisten Anrufe. Ändern Sie nur, was für dieses Gespräch wichtig ist.')}</p><div class="grid2">${field(T('Result','Ergebnis'),'Save the spoken answer in SHPROHLI',{options:['Save the spoken answer in SHPROHLI','Ask the recipient to send something','Deliver a message only']})}${field(T('Addressing','Anrede'),'Formal (default)',{options:['Formal (default)','Automatic by relationship','Informal']})}${field(T('Tone','Ton'),'Automatic',{options:['Automatic','Formal','Neutral','Friendly']})}${field('Voicemail','Do not leave call details',{options:['Do not leave call details','Leave a neutral message']})}</div>${field(T('Delivery instruction','Übermittlungsanweisung'),'',{placeholder:'Ask them to send it through the agreed channel',optional:true})}${field(T('Audio retention','Aufbewahrung der Aufnahme'),'Keep for 7 days',{options:['Delete after final transcript','Keep for 7 days','Keep for 30 days']})}${field(T('Additional context','Zusätzlicher Kontext'),'',{type:'textarea',optional:true,placeholder:'Relevant background, correspondence or organisation details'})}${check(T('Allow language switching','Sprachwechsel erlauben'))}${field(T('Fallback language','Ausweichsprache'),'English (UK)',{options:callLanguages,help:T('The assistant may use one selected fallback language.','Der Assistent darf eine ausgewählte Ausweichsprache verwenden.')})}${field(T('Information the assistant may share','Informationen, die der Assistent weitergeben darf'),'',{type:'textarea',optional:true,help:T('Enter actual verified facts, one per line. Examples are never prefilled.','Geben Sie bestätigte Fakten ein, jeweils eine pro Zeile. Beispiele werden nie vorausgefüllt.')})}</div></details></div><div class="form-foot"><small data-progress-help>${filled?'5':'0'}/5 ${T('required fields completed','Pflichtfelder ausgefüllt')}</small>${submit(state('preparing')?T('Preparing…','Wird vorbereitet…'):T('Review call','Anruf prüfen'),!filled||state('preparing'))}</div></form>`;
}
function dashboardPage(){let rows=state('empty')?empty(T('No calls yet','Noch keine Anrufe'),T('Your prepared and completed calls will appear here.','Ihre vorbereiteten und abgeschlossenen Anrufe erscheinen hier.')):[[T('Municipal office','Gemeinde'),'Completed','7 Sep 2026','completed'],[T('Repair service','Reparaturdienst'),'Stopped','6 Sep 2026','stopped'],[T('Course provider','Kursanbieter'),'Review required','6 Sep 2026','review']].map(([name,status,date,s])=>link(`<strong>${name}</strong><p>${badge(status,status==='Stopped'?'neutral':status==='Review required'?'warning':'')} <small>${date}</small></p>`,'call',s,'history-item')).join('');return header('customer')+`<div class="mobile-tabs">${btn(T('New call','Neuer Anruf'),'default',state('history')?'':'active')}${btn(T('History','Verlauf'),'history',state('history')?'active':'')}</div><main id="main-content" class="dashboard ${state('history')?'history-mode':''}"><aside class="history"><div class="stack"><h2>${T('Recent calls','Letzte Anrufe')}</h2>${field(T('Search by recipient','Nach Empfänger suchen'),'',{type:'search',placeholder:T('Search by recipient','Nach Empfänger suchen')})}${field(T('Status','Status'),'All statuses',{options:['All statuses','Completed','Stopped','Review required','In progress','Failed']})}</div><div class="history-list">${rows}</div><p class="help" style="margin-top:48px">${T('The recipient chooses whether to continue.','Die angerufene Person entscheidet, ob sie fortfahren möchte.')}</p></aside><section class="callform">${callForm()}</section></main>`}

function transcript(final=true){const lines=[['Sebastian','~0:00','Guten Tag. Ich rufe als KI-Assistent im Namen von Nina Keller an. Ist es in Ordnung, kurz weiterzusprechen?'],['Municipal office','~0:11','Ja, gerne.'],['Sebastian','~0:21','Ist ihr Formular eingegangen?'],['Municipal office','~0:32','Ja. Es fehlt noch eine Kopie des Reisepasses.'],['Sebastian','~0:48','Vielen Dank. Ich gebe die Information weiter.']];return `<div class="transcript ${!final?'speech-live':''}">${lines.slice(0,final?5:4).map(([who,time,text])=>`<div class="utterance"><strong>${who}</strong><time>${time}</time><p lang="de">${text}</p></div>`).join('')}</div><p class="help" style="margin-top:20px">${T('AI-generated. Check important names, dates, numbers and commitments against the recording.','KI-generiert. Prüfen Sie wichtige Namen, Daten, Zahlen und Zusagen anhand der Aufnahme.')}</p>`}
function reviewPlan(){return `${section(T('What SHPROHLI will do','Was SHPROHLI tun wird'),'<p>'+T('Check whether the residence form arrived and identify any missing documents. Save the spoken answer in SHPROHLI.','Prüfen, ob das Formular eingegangen ist, und fehlende Unterlagen erfragen. Die gesprochene Antwort in SHPROHLI speichern.')+'</p>')}${section(T('Call settings','Anrufeinstellungen'),`<div class="row">${badge(T('Neutral tone','Neutraler Ton'),'neutral')}${badge(T('Formal addressing','Formelle Anrede'),'neutral')}${badge(T('Answers saved in SHPROHLI','Antworten in SHPROHLI speichern'),'neutral')}</div>`)}${section(T('How the call starts','So beginnt der Anruf'),'<p lang="de">Guten Tag. Ich rufe als KI-Assistent im Namen von Nina Keller an. Ist es in Ordnung, kurz weiterzusprechen?</p>')}${section(T('Questions it may ask','Mögliche Fragen'),'<ol class="stack tight"><li>Ist das Formular eingegangen?</li><li>Fehlen noch Unterlagen?</li><li>Wie können die fehlenden Unterlagen eingereicht werden?</li></ol>')}${section(T('Approved information','Freigegebene Informationen'),facts([['Name','Nina Keller'],[T('Request','Anliegen'),T('Residence form sent on 2 September 2026','Formular am 2. September 2026 gesendet')]]))}${section(T('Safety rules','Sicherheitsregeln'),'<p>'+T('Do not invent facts or make commitments outside the approved plan. Respect refusal and end the call. Do not leave call details on voicemail.','Keine Fakten erfinden oder Zusagen ausserhalb des freigegebenen Plans machen. Eine Ablehnung respektieren und den Anruf beenden. Keine Anrufdetails auf der Mailbox hinterlassen.')+'</p>')}`}
function recording(){return `<div class="audio"><button type="button" data-audio-toggle aria-label="${T('Play recording','Aufnahme abspielen')}">${T('Play','Start')}</button><time>0:00</time><input type="range" min="0" max="66" value="0" aria-label="${T('Recording position','Aufnahmeposition')}"><time>1:06</time></div><div class="row between"><small>${T('Keep for 7 days','7 Tage aufbewahren')}</small>${btn(T('Delete recording','Aufnahme löschen'),'delete-recording','quiet danger')}</div>`}
function callPage(){let s=ctx.state,done=['completed','provisional','transcribing','transcript-failed','no-recording','recording-deleted','delete-recording','delete-call','feedback-saved'].includes(s),live=['live','approval','reconnecting','dialing'].includes(s);let status=done?T('Call completed','Anruf abgeschlossen'):live?(state('dialing')?T('Dialing','Verbindung wird aufgebaut'):state('approval')?T('Awaiting decision','Entscheidung erforderlich'):T('Call in progress','Anruf läuft')):({failed:T('Call failed','Anruf fehlgeschlagen'),stopped:T('Call stopped','Anruf gestoppt'),clarification:T('Needs one detail','Eine Angabe fehlt'),blocked:T('Needs changes','Änderungen erforderlich'),archived:T('Archived call plan','Archivierter Anrufplan')})[s]||T('Ready to call','Bereit zum Anruf');let main='',aside='',dialog='';
 if(s==='edit')return header('customer')+`<main class="container" id="main-content">${link(T('Back to call plan','Zurück zum Anrufplan'),'call','review')}<div class="callform">${callForm()}</div></main>`;
 if(done){
 const provisional=state('provisional'),hasFinal=!['transcribing','transcript-failed','no-recording'].includes(s);
 main=`<nav class="subnav transcript-tabs" aria-label="${T('Transcript version','Transkriptversion')}">${btn(T('Final transcript','Endgültiges Transkript'),'completed',!provisional?'active':'')}${btn(T('Provisional transcript','Vorläufiges Transkript'),'provisional',provisional?'active':'')}<a class="feedback-jump" href="#call-feedback">${T('Rate call quality','Anrufqualität bewerten')}</a></nav><div class="row between transcript-heading"><div><h2>${provisional?T('Provisional transcript','Vorläufiges Transkript'):T('Final transcript','Endgültiges Transkript')}</h2><p class="help">${provisional?T('Captured during the call. Wording may differ from the final transcript.','Während des Anrufs erfasst. Der Wortlaut kann vom endgültigen Transkript abweichen.'):T('Created from the call recording.','Aus der Anrufaufnahme erstellt.')}</p></div>${hasFinal&&!provisional?`<div class="actions">${btn(T('Copy transcript','Transkript kopieren'))}${btn(T('Download PDF','PDF herunterladen'))}</div>`:''}</div>`;
 main+=provisional?transcript(false):state('transcribing')?note(T('The final transcript is being created. The provisional transcript remains available below.','Das endgültige Transkript wird erstellt. Das vorläufige Transkript bleibt unten verfügbar.'),'info')+transcript(false):state('transcript-failed')?note(T('Final transcription failed. You can retry while the recording is available.','Die endgültige Transkription ist fehlgeschlagen. Solange die Aufnahme verfügbar ist, können Sie es erneut versuchen.'),'error')+`<div class="actions">${btn(T('Retry final transcript','Transkription erneut versuchen'),'transcribing','primary')}</div>`:state('no-recording')?empty(T('No recording available','Keine Aufnahme verfügbar'),T('A final transcript cannot be created without a recording. The provisional transcript may still be available.','Ohne Aufnahme kann kein endgültiges Transkript erstellt werden. Das vorläufige Transkript ist möglicherweise noch verfügbar.')):transcript(true)+`<details class="disclosure" style="margin-top:24px"><summary>${T('How this transcript was created','So wurde dieses Transkript erstellt')}</summary><div><p class="help">${T('Generated after the call from the recording. Speaker labels and timestamps are approximate.','Nach dem Anruf aus der Aufnahme erstellt. Sprecherzuordnung und Zeitstempel sind ungefähr.')}</p>${btn(T('Regenerate final transcript','Endgültiges Transkript neu erstellen'),'transcribing','quiet')}</div></details>`;
 aside=section(T('Recording','Aufnahme'),state('recording-deleted')?note(T('The recording has been deleted.','Die Aufnahme wurde gelöscht.')):state('no-recording')?'<p class="help">'+T('No recording is available.','Keine Aufnahme verfügbar.')+'</p>':recording())+completedFeedback(hasFinal)+section(T('Call goal','Anrufziel'),'<p>'+T('Check whether the residence form arrived and whether documents are missing.','Prüfen, ob das Formular eingegangen ist und ob Unterlagen fehlen.')+'</p>')+section(T('Call data','Anrufdaten'),btn(T('Delete call data','Anrufdaten löschen'),'delete-call','danger'));
 }else if(live){main=state('dialing')?note(T('Connecting to the recipient. Conversation processing begins only after consent.','Die Verbindung wird aufgebaut. Die Gesprächsverarbeitung beginnt erst nach Zustimmung.'),'info'):state('reconnecting')?note(T('Reconnecting to live updates. The call may still be in progress.','Die Live-Verbindung wird wiederhergestellt. Der Anruf kann weiterhin laufen.'),'warning'):note(T('Live · Recipient consent received','Live · Zustimmung erhalten'));main+=`<div class="row between" style="margin:28px 0"><div><h2>${T('Live transcript','Live-Transkript')}</h2><p class="help">${T('Provisional · updates during the call','Vorläufig · wird während des Anrufs aktualisiert')}</p></div>${btn(T('Jump to latest','Zum neuesten Beitrag'))}</div>${state('dialing')?empty(T('Waiting for the conversation','Warten auf das Gespräch'),T('The assistant will introduce itself first.','Der Assistent stellt sich zuerst vor.')):transcript(false)}`;if(state('approval'))main+=section(T('Your decision is needed','Ihre Entscheidung ist erforderlich'),note(T('The recipient asked for an additional detail. Review the proposed disclosure before it is shared.','Die angerufene Person fragt nach einer zusätzlichen Angabe. Prüfen Sie die vorgeschlagene Offenlegung vor der Weitergabe.'),'warning')+'<div class="surface"><p>„Nina Keller kann eine Kopie des Dokuments per E-Mail einreichen.“</p></div>'+`<div class="actions">${btn(T('Approve','Freigeben'),'live','primary')}${btn(T('Do not disclose','Nicht weitergeben'),'live')}</div>`);aside=section(T('Call details','Anrufdetails'),facts([[T('Primary language','Hauptsprache'),'German (Switzerland)'],[T('Language switching','Sprachwechsel'),T('Disabled','Deaktiviert')],[T('Assistant','Assistent'),'Sebastian'],[T('Assistance reason','Unterstützungsgrund'),T('Not disclosed','Nicht offengelegt')],[T('Audio retention','Audio-Aufbewahrung'),T('7 days','7 Tage')]]))+section(T('Call controls','Anrufsteuerung'),btn(T('Stop call','Anruf stoppen'),'stopped','danger'));}
 else if(['failed','stopped','archived'].includes(s)){main=empty(status,state('archived')?T('This older plan can no longer be executed. Edit and prepare a current plan.','Dieser ältere Plan kann nicht mehr ausgeführt werden. Bearbeiten und erstellen Sie einen aktuellen Plan.'):state('failed')?T('The call could not be completed. Review the call details before trying again.','Der Anruf konnte nicht abgeschlossen werden. Prüfen Sie die Details vor einem erneuten Versuch.'):T('The call was stopped. No further conversation will take place in this call.','Der Anruf wurde gestoppt. In diesem Anruf findet kein weiteres Gespräch statt.'),link(T('Prepare a new call','Neuen Anruf vorbereiten'),'new-call','filled','button primary'));aside=section(T('Call details','Anrufdetails'),facts([['Language','German (Switzerland)'],['Consent','Not recorded'],['Recording','Not available']]));}
 else {main=state('clarification')?note(T('One detail is needed before this plan can be approved.','Vor der Freigabe wird eine weitere Angabe benötigt.'),'warning')+form(`${field(T('When did you send the form?','Wann haben Sie das Formular gesendet?'),'',{type:'textarea',required:true})}${submit(T('Update call plan','Anrufplan aktualisieren'))}`,'review'):state('blocked')?note(T('This request needs changes before a call can be prepared. Keep the task within supported everyday communication.','Diese Anfrage muss geändert werden. Beschränken Sie die Aufgabe auf unterstützte Alltagskommunikation.'),'error')+`<div class="actions">${btn(T('Edit call plan','Anrufplan bearbeiten'),'edit','primary')}</div>`:reviewPlan();aside=section(T('Call details','Anrufdetails'),facts([[T('Recipient','Empfänger'),T('Municipal office','Gemeinde')],[T('Phone number','Telefonnummer'),'+41 44 123 45 67'],[T('Call language','Anrufsprache'),'German (Switzerland)'],[T('Assistant','Assistent'),'Sebastian'],[T('Audio retention','Audio-Aufbewahrung'),T('7 days','7 Tage')]]));if(!['clarification','blocked'].includes(s))aside+=section(T('Your approval','Ihre Freigabe'),'<p class="help">'+T('Review the goal, opening and information before starting.','Prüfen Sie Ziel, Einleitung und Informationen, bevor Sie starten.')+'</p>'+`<div class="stack tight">${btn(T('Approve and call','Freigeben und anrufen'),'confirm-start','primary')}${btn(T('Edit call plan','Anrufplan bearbeiten'),'edit')}</div>`);}
 if(state('confirm-start'))dialog=modal(T('Start this phone call?','Diesen Anruf starten?'),T('SHPROHLI will call Municipal office at +41 44 123 45 67 using the approved plan.','SHPROHLI ruft die Gemeinde unter +41 44 123 45 67 mit dem genehmigten Plan an.'),facts([[T('Call language','Anrufsprache'),'German (Switzerland)'],[T('Credit reservation','Guthabenreservierung'),'1']]),T('Start call','Anruf starten'),'dialing',false,'review');
 if(state('delete-recording'))dialog=modal(T('Delete recording?','Aufnahme löschen?'),T('This permanently deletes the audio recording. The existing transcript remains available.','Dadurch wird die Audioaufnahme dauerhaft gelöscht. Das bestehende Transkript bleibt verfügbar.'),'',T('Delete recording','Aufnahme löschen'),'recording-deleted',true,'completed');
 if(state('delete-call'))dialog=modal(T('Delete call data?','Anrufdaten löschen?'),T('Personal call content, recording and transcripts will be deleted. Limited security and accounting records may remain.','Persönliche Anrufinhalte, Aufnahme und Transkripte werden gelöscht. Begrenzte Sicherheits- und Abrechnungsdaten können verbleiben.'),`<div class="stack">${field(T('Current password','Aktuelles Passwort'),'',{type:'password'})}${field(T('Type DELETE to confirm','Zur Bestätigung DELETE eingeben'),'',{placeholder:'DELETE'})}</div>`,T('Delete call data','Anrufdaten löschen'),'stopped',true,'completed');
 return header('customer')+`<main class="container" id="main-content"><div style="margin-bottom:28px">${link(T('All calls','Alle Anrufe'),'new-call','history')}</div><div class="intro"><div class="row between"><h1>${T('Municipal office','Gemeinde')}</h1>${badge(status,['failed','blocked'].includes(s)?'danger':['approval','clarification'].includes(s)?'warning':'')}</div><p class="help">German (Switzerland) · 7 Sep 2026${done?' · 01:06':''}</p></div><div class="call-layout ${done?'completed-layout':''}"><section class="stack">${main}</section><aside>${aside}</aside></div></main>${dialog}`;
}

function accountPage(){let s=ctx.state,tab=['usage'].includes(s)?'usage':['security','revoke','signout-all'].includes(s)?'security':['privacy','delete','deletion-queued','deletion-waiting','deletion-support'].includes(s)?'privacy':'default',body='',dialog='';const nav=[['Profile','Profil','default'],['Usage','Nutzung','usage'],['Data & privacy','Daten & Datenschutz','privacy'],['Security','Sicherheit','security']].map(([en,de,id])=>link(T(en,de),'account',id,tab===id?'active':'')).join('');
 if(tab==='default'){body=state('saved')?note(T('Your changes were saved.','Ihre Änderungen wurden gespeichert.')):state('error')?note(T('The change could not be saved. Your current details are still active.','Die Änderung konnte nicht gespeichert werden. Ihre bisherigen Angaben bleiben aktiv.'),'error'):'';body+=section(T('Identity','Identität'),facts([[T('First and last name','Vor- und Nachname'),`<div class="row between"><strong>Nina Keller</strong>${btn(T('Edit name','Namen bearbeiten'),'edit-name','quiet')}</div>`],[T('Email','E-Mail'),`<div class="row between"><span>nina@example.com</span>${btn(T('Change','Ändern'),'email','quiet')}</div>`],[T('Verified mobile','Bestätigtes Mobiltelefon'),`<div class="row between"><span>+41 79 ••• 45 67</span>${btn(T('Change','Ändern'),'phone','quiet')}</div>`],[T('Role','Rolle'),T('User','Benutzer')],[T('Status','Status'),badge(T('Active','Aktiv'))],[T('Last sign-in','Letzte Anmeldung'),'7 Sep 2026, 09:30']]));
 if(state('edit-name'))body+=section(T('Edit your name','Namen bearbeiten'),form(`<div class="grid2">${field(T('First name','Vorname'),'Nina',{maxLength:80,required:true})}${field(T('Last name','Nachname'),'Keller',{maxLength:80,required:true})}</div><div class="actions">${submit(T('Save name','Namen speichern'))}${btn(T('Cancel','Abbrechen'),'default')}</div>`,'saved'));
 if(['email','email-code','phone','phone-code'].includes(s)){const phone=s.startsWith('phone'),verify=s.endsWith('code');body+=section(phone?T('Change mobile phone','Mobiltelefon ändern'):T('Change email','E-Mail ändern'),form(`${note(verify?phone?T('Enter the SMS code in this same signed-in session.','Geben Sie den SMS-Code in derselben angemeldeten Sitzung ein.'):T('Enter the 6-digit code sent to your new email. It expires in 10 minutes.','Geben Sie den sechsstelligen Code aus der neuen E-Mail ein. Er läuft nach 10 Minuten ab.'):phone?T('Your old number stays active until the new number is verified. Other sessions will then be signed out.','Ihre bisherige Nummer bleibt bis zur Bestätigung aktiv. Danach werden andere Sitzungen abgemeldet.'):T('Your current email stays active until the new address is verified. Other sessions will then be signed out.','Ihre bisherige E-Mail bleibt bis zur Bestätigung aktiv. Danach werden andere Sitzungen abgemeldet.'))}${verify?field(phone?T('SMS code','SMS-Code'):T('Email code','E-Mail-Code'),'',{numeric:true,minLength:phone?4:6,maxLength:phone?10:6,required:true,placeholder:'000000'}):field(phone?T('New Swiss mobile number','Neue Schweizer Mobilnummer'):T('New email','Neue E-Mail'),'',{type:phone?'tel':'email',required:true,placeholder:phone?'+41791234567':'nina.new@example.com'})+field(T('Current password','Aktuelles Passwort'),'',{type:'password',required:true,maxLength:128})}<div class="actions">${submit(verify?T('Verify and save','Bestätigen und speichern'):T('Send verification code','Bestätigungscode senden'))}${btn(T('Cancel','Abbrechen'),'default')}</div>`,verify?'saved':phone?'phone-code':'email-code'));}
 } else if(tab==='usage'){body=section(T('Call credits','Anrufguthaben'),facts([[T('Current balance','Aktueller Stand'),'<strong style="font-size:32px">2</strong> '+T('credits','Guthaben')],[T('Active call','Aktiver Anruf'),T('No active call','Kein aktiver Anruf')]])+`<div class="actions">${link(T('Redeem a promo code','Aktionscode einlösen'),'redeem','default','button')}</div>`)+section(T('Credit history','Guthabenverlauf'),table([T('Transaction','Buchung'),T('Date','Datum'),T('Change','Änderung')],[['Signup grant','6 Sep 2026','+3'],['Call reservation','7 Sep 2026','−1'],['Connected call charge','7 Sep 2026','0']]))+note(T('A reservation and a connected-call charge are separate ledger entries. A zero charge entry does not mean a free call.','Reservierung und Abrechnung eines verbundenen Anrufs sind separate Buchungen. Ein Eintrag mit 0 bedeutet keinen kostenlosen Anruf.'));
 } else if(tab==='security'){body=section(T('Active sessions','Aktive Sitzungen'),table([T('Browser / device','Browser / Gerät'),T('Activity','Aktivität'),T('Actions','Aktionen')],[[`<strong>Chrome · Windows</strong><small>${badge(T('This session','Diese Sitzung'))}</small>`,'Signed in 7 Sep 2026, 09:30<br><small>Last active just now · Expires 7 Oct 2026</small>',T('Current session','Aktuelle Sitzung')],['Safari · iPhone','Signed in 6 Sep 2026, 18:10<br><small>Last active 6 Sep 2026 · Expires 6 Oct 2026</small>',btn(T('Revoke','Widerrufen'),'revoke')]]))+section(T('Sign-in controls','Anmeldesteuerung'),`<div class="stack"><p class="muted">${T('End this browser session or sign out on every device.','Beenden Sie diese Browsersitzung oder melden Sie sich auf allen Geräten ab.')}</p><div class="actions">${link(T('Sign out of this browser','Diesen Browser abmelden'),'login','default','button')}${btn(T('Sign out everywhere','Überall abmelden'),'signout-all','danger')}</div></div>`);if(state('revoke'))dialog=modal(T('Revoke this session?','Diese Sitzung widerrufen?'),T('Safari on iPhone will be signed out. Your current session stays active.','Safari auf dem iPhone wird abgemeldet. Ihre aktuelle Sitzung bleibt aktiv.'),'',T('Revoke session','Sitzung widerrufen'),'security',true,'security');if(state('signout-all'))dialog=modal(T('Sign out everywhere?','Überall abmelden?'),T('All sessions, including this browser, will be signed out.','Alle Sitzungen, einschliesslich dieses Browsers, werden abgemeldet.'),'',T('Sign out everywhere','Überall abmelden'),'security',true,'security');
 } else {body=section(T('Export your data','Ihre Daten exportieren'),'<p>'+T('Download your profile, sessions, credit history, calls, transcripts and feedback as JSON.','Laden Sie Profil, Sitzungen, Guthabenverlauf, Anrufe, Transkripte und Rückmeldungen als JSON herunter.')+'</p>'+btn(T('Download my data','Meine Daten herunterladen')))+section(T('Delete your account','Konto löschen'),'<p>'+T('Permanently delete your account and personal call data. This cannot be undone.','Löschen Sie Ihr Konto und persönliche Anrufdaten dauerhaft. Dies kann nicht rückgängig gemacht werden.')+'</p>'+btn(T('Delete account','Konto löschen'),'delete','danger'));if(s.startsWith('deletion-'))body=section(T('Account deletion','Kontolöschung'),note(state('deletion-waiting')?T('Waiting for your active call to finish. The deletion request is saved.','Es wird auf das Ende Ihres aktiven Anrufs gewartet. Der Löschauftrag ist gespeichert.'):state('deletion-support')?T('Deletion needs support. The request remains recorded; contact support if you need help.','Die Löschung benötigt Unterstützung. Der Auftrag bleibt gespeichert. Wenden Sie sich bei Bedarf an den Support.'):T('Deletion is queued. Provider and account data will be processed in the background.','Die Löschung ist vorgemerkt. Anbieter- und Kontodaten werden im Hintergrund verarbeitet.'),state('deletion-support')?'warning':'info')+link(T('Contact support','Support kontaktieren'),'support'));if(state('delete'))dialog=modal(T('Permanently delete your account?','Konto dauerhaft löschen?'),T('Your account, personal call content and provider recordings will be deleted. This action cannot be undone.','Ihr Konto, persönliche Anrufinhalte und Aufnahmen beim Anbieter werden gelöscht. Diese Aktion kann nicht rückgängig gemacht werden.'),`<div class="stack">${field(T('Current password','Aktuelles Passwort'),'',{type:'password',required:true})}${field(T('Type DELETE MY ACCOUNT','DELETE MY ACCOUNT eingeben'),'',{placeholder:'DELETE MY ACCOUNT',required:true})}</div>`,T('Delete my account','Mein Konto löschen'),'deletion-queued',true,'privacy');}
 return header('customer')+`<main class="container" id="main-content">${intro(T('Profile, usage, and sessions','Profil, Nutzung und Sitzungen'),T('Review your profile, call credits, active sessions and personal data controls.','Prüfen Sie Profil, Anrufguthaben, aktive Sitzungen und persönliche Daten.'),T('Account','Konto'))}<div class="settings-layout"><nav class="sidenav" aria-label="Account sections">${nav}</nav><div>${body}</div></div></main>${dialog}`;
}

function errorPage(){const messages={loading:[T('Loading your account…','Ihr Konto wird geladen…'),T('Checking access and loading the latest data.','Zugriff wird geprüft und aktuelle Daten werden geladen.')],error:[T('Something could not be loaded','Ein Inhalt konnte nicht geladen werden'),T('Your input has been preserved. Try loading this page again.','Ihre Eingaben bleiben erhalten. Laden Sie diese Seite erneut.')],'signed-out':[T('Sign in to continue','Melden Sie sich an'),T('Your session has ended. Sign in to open this page.','Ihre Sitzung ist beendet. Melden Sie sich an, um diese Seite zu öffnen.')],forbidden:[T('Access required','Zugriff erforderlich'),T('Your current role does not have access to this workspace.','Ihre aktuelle Rolle hat keinen Zugriff auf diesen Arbeitsbereich.')],'not-found':[T('Page not found','Seite nicht gefunden'),T('This page does not exist or is no longer available.','Diese Seite existiert nicht oder ist nicht mehr verfügbar.')],offline:[T('Connection interrupted','Verbindung unterbrochen'),T('Check your connection and try again.','Prüfen Sie Ihre Verbindung und versuchen Sie es erneut.')]};const [title,text]=messages[ctx.state]||messages.error;return header()+`<main class="error-page" id="main-content">${intro(title,text,state('not-found')?'404':'')}${state('loading')?'<div class="stack" role="status"><div class="skeleton"></div><div class="skeleton tall"></div><div class="skeleton" style="width:60%"></div></div>':`<div class="actions">${link(state('signed-out')?T('Sign in','Anmelden'):T('Back to home','Zur Startseite'),state('signed-out')?'login':'landing','default','button primary')}${state('error')||state('offline')?btn(T('Retry','Erneut versuchen'),'loading'):''}</div>`}</main>`}

function componentsPage(){return header('customer')+`<main id="main-content" class="container">${intro('Components','Design reference · states, dimensions and theme pairs.','SHPROHLI DESIGN SYSTEM')}${section('Buttons',`<div class="row">${btn('Primary action','default','primary')}${btn('Secondary action','default')}${btn('Text action','default','quiet')}${btn('Danger action','dialogs','danger')}<button class="primary" disabled>Unavailable</button><button class="primary" disabled>Preparing…</button></div>`)}${section('Form fields',`<div class="grid2">${field('Default field','',{placeholder:'Enter a value',help:'Persistent helper text.'})}${field('Filled field','Nina Keller')}${field('Invalid field','not-an-email',{error:'Enter a valid email address.'})}${field('Disabled field','Not available',{disabled:true})}${field('Select','Option A',{options:['Option A','Option B']})}${field('Long answer','',{type:'textarea',help:'0 / 4000 characters'})}</div>${check('Checkbox label with sufficient line height')}${segmented('Radio group',['Yes','Partly','No'])}`)}${section('Status and feedback',`<div class="row">${badge('Completed')}${badge('Review required','warning')}${badge('Failed','danger')}${badge('Not available','neutral')}</div><div class="stack">${note('Changes saved.')}${note('One detail is needed before continuing.','warning')}${note('The request could not be completed. Try again.','error')}${note('The final transcript is being created.','info')}</div>`)}${section('Theme tokens',`<div class="swatches">${[['Canvas','var(--bg)'],['Surface','var(--surface)'],['Primary','var(--accent)'],['Primary text','var(--ink)'],['Secondary text','var(--muted)'],['Danger','var(--danger)'],['Warning','var(--warning)'],['Focus','var(--focus)']].map(([l,c])=>`<div class="swatch"><div style="background:${c}"></div><p>${l}</p></div>`).join('')}</div>`)}${section('Loading and empty',`<div class="stack"><div class="skeleton"></div><div class="skeleton" style="width:65%"></div></div>${empty('No calls yet','Your prepared calls will appear here.',link('Prepare a call','new-call','default','button primary'))}`)}</main>${state('dialogs')?modal('Confirm this action?','Explain what will change and identify the affected object.','','Confirm','default',false,'default'):''}`}

function completedFeedback(hasFinal){
 const saved=state('feedback-saved');
 const group=(legend,name,values,labels)=>`<fieldset class="feedback-fieldset"><legend>${legend}</legend><div class="segmented">${values.map((value,i)=>`<label><input type="radio" name="${name}" value="${value}" ${name==='goal-result'?'required':''} ${saved&&i===0?'checked':''}><span>${labels[i]}</span></label>`).join('')}</div></fieldset>`;
 return `<section class="section feedback-section" id="call-feedback" aria-labelledby="feedback-title" tabindex="-1"><div><span class="eyebrow">${T('Call quality','Anrufqualität')}</span><h2 id="feedback-title">${T('Your feedback','Ihre Rückmeldung')}</h2><p class="help">${T('Tell us how the call went and how accurate the transcript is.','Teilen Sie uns mit, wie der Anruf verlief und wie genau das Transkript ist.')}</p></div><form class="stack" data-feedback-form>${group(T('Was your goal achieved?','Wurde Ihr Ziel erreicht?'),'goal-result',['yes','partly','no'],[T('Yes','Ja'),T('Partly','Teilweise'),T('No','Nein')])}${hasFinal?group(T('Transcript quality','Transkriptqualität'),'transcript-quality',['good','some_errors','poor'],[T('Good','Gut'),T('Some errors','Einige Fehler'),T('Poor','Schlecht')]):`<div><strong class="help">${T('Transcript quality','Transkriptqualität')}</strong><p class="help">${T('Available when the final transcript is ready.','Verfügbar, sobald das endgültige Transkript bereit ist.')}</p></div>`}${field(T('Comment','Kommentar'),saved?T('The answer was clear and the names were correct.','Die Antwort war klar und die Namen waren korrekt.'):'',{type:'textarea',rows:3,maxLength:500,optional:true})}<small data-feedback-count>0 / 500</small><div class="stack tight"><button class="primary" type="submit" ${saved?'':'disabled'}>${saved?T('Update feedback','Rückmeldung aktualisieren'):T('Save feedback','Rückmeldung speichern')}</button><p class="help" data-feedback-status role="status">${saved?T('Your feedback was saved.','Ihre Rückmeldung wurde gespeichert.'):''}</p></div></form></section>`;
}
